<template>
<section :class="[$style.workspace,{[$style.systemOpen]:systemView!==null}]">
	<aside :class="$style.rail">
		<div :class="$style.railHeader"><strong>{{ l.channels }}</strong><button v-if="canManageChannels" class="_button" :class="$style.iconButton" @click="addOpen=!addOpen"><i class="ti ti-plus"></i></button></div>
		<div v-if="canManageChannels&&addOpen" :class="$style.creator">
			<form @submit.prevent="createCategory"><small>{{ l.category }}</small><div><input v-model="newCategoryName" maxlength="64" :placeholder="l.category"><button class="_button" :disabled="!newCategoryName.trim()"><i class="ti ti-plus"></i></button></div></form>
			<form @submit.prevent="createChannel">
				<small>{{ l.channels }}</small>
				<input v-model="newChannelName" maxlength="64" :placeholder="l.defaultChannelName">
				<select v-model="newChannelKind">
					<option value="text">テキスト</option>
					<option value="announcement">お知らせ</option>
					<option value="media">メディア</option>
					<option value="forum">フォーラム</option>
					<option v-if="voiceEnabled" value="voice">ボイス</option>
				</select>
				<select v-model="newChannelParentId"><option value="">{{ l.noCategory }}</option><option v-for="c in categoryChannels" :key="c.id" :value="c.id">{{ c.name }}</option></select>
				<button class="_button" :class="$style.yellow" :disabled="!newChannelName.trim()"><i class="ti ti-plus"></i> {{ l.create }}</button>
			</form>
		</div>
		<div :class="$style.filter"><i class="ti ti-search"></i><input v-model="filter" :placeholder="l.search"></div>
		<div :class="$style.railBody">
			<div :class="$style.fixed">
				<button class="_button" :class="[$style.channel,{[$style.active]:systemView==='info'}]" @click="openSystem('info')"><i class="ti ti-info-circle"></i><span>{{ l.info }}</span></button>
				<button class="_button" :class="[$style.channel,{[$style.active]:systemView==='rules'}]" @click="openSystem('rules')"><i class="ti ti-notebook"></i><span>{{ l.rules }}</span></button>
				<button class="_button" :class="[$style.channel,{[$style.active]:systemView==='announcements'}]" @click="openSystem('announcements')"><i class="ti ti-speakerphone"></i><span>{{ l.announcements }}</span></button>
				<button class="_button" :class="[$style.channel,{[$style.active]:systemView==='members'}]" @click="openSystem('members')"><i class="ti ti-users"></i><span>{{ l.members }}</span></button>
			</div>
			<section v-for="group in groups" :key="group.id" :class="$style.group">
				<div :class="$style.groupTitleRow"><div :class="$style.groupTitle">{{ group.name }}</div><button v-if="canManageChannels" class="_button" :class="$style.deleteChannel" :title="l.delete" @click.stop="deleteChannel(group.id)"><i class="ti ti-trash"></i></button></div>
				<div v-for="c in group.channels" :key="c.id" :class="$style.channelLine"><button class="_button" :class="[$style.channel,{[$style.active]:systemView===null&&selected?.id===c.id}]" @click="selectChannel(c)"><i :class="channelIcon(c)"></i><span>{{ c.name }}</span></button><button v-if="canManageChannels" class="_button" :class="$style.deleteChannel" :title="l.delete" @click.stop="deleteChannel(c.id)"><i class="ti ti-trash"></i></button></div>
				<div v-if="group.channels.length===0" :class="$style.emptyCategory">—</div>
			</section>
			<section v-if="textChannels.length" :class="$style.group"><div :class="$style.groupTitle">{{ l.textChannels }}</div><div v-for="c in textChannels" :key="c.id" :class="$style.channelLine"><button class="_button" :class="[$style.channel,{[$style.active]:systemView===null&&selected?.id===c.id}]" @click="selectChannel(c)"><i :class="channelIcon(c)"></i><span>{{ c.name }}</span></button><button v-if="canManageChannels" class="_button" :class="$style.deleteChannel" :title="l.delete" @click.stop="deleteChannel(c.id)"><i class="ti ti-trash"></i></button></div></section>
			<section v-if="voiceChannels.length" :class="$style.group"><div :class="$style.groupTitle">{{ l.voiceChannels }}</div><div v-for="c in voiceChannels" :key="c.id" :class="$style.channelLine"><button class="_button" :class="[$style.channel,{[$style.active]:systemView===null&&selected?.id===c.id}]" @click="selectChannel(c)"><i class="ti ti-volume"></i><span>{{ c.name }}</span></button><button v-if="canManageChannels" class="_button" :class="$style.deleteChannel" :title="l.delete" @click.stop="deleteChannel(c.id)"><i class="ti ti-trash"></i></button></div></section>
		</div>
	</aside>

	<main :class="$style.main">
		<template v-if="systemView==='info'"><XHeader icon="ti ti-info-circle" :title="l.info"/><div :class="$style.scroll"><section :class="$style.infoCard"><h3><i class="ti ti-pin"></i> {{ l.pins }}</h3><div v-if="pins.length"><div v-for="pin in pins" :key="pin.id" :class="$style.pin">{{ pin.label||pin.url||pin.targetId }}</div></div><p v-else>{{ l.noInformation }}</p></section></div></template>
		<template v-else-if="systemView==='rules'"><XHeader icon="ti ti-notebook" :title="l.rules"/><div :class="$style.scroll"><NookCommunityRules :communityId="communityId" :canManage="canManageRules"/></div></template>
		<template v-else-if="systemView==='announcements'"><XHeader icon="ti ti-speakerphone" :title="l.announcements"/><div :class="$style.scroll"><NookCommunityAnnouncements :communityId="communityId" :canManage="canManageAnnouncements"/></div></template>
		<template v-else-if="systemView==='members'"><XHeader icon="ti ti-users" :title="l.members"/><div :class="$style.scroll"><NookCommunityMembers :communityId="communityId" :canManage="canManageMembers" :canManageRoles="canManageRoles"/></div></template>
		<NookCommunityVoice v-else-if="voiceEnabled&&selected?.kind==='voice'" :communityId="communityId" :channel="selected" :channels="selectable" :canManage="canManageVoice"/>
		<template v-else-if="selected">
			<header :class="$style.header"><div :class="$style.heading"><i :class="channelIcon(selected)"></i><div><strong>{{ selected.name }}</strong><small v-if="selected.topic&&selected.topic!==CATEGORY_TOPIC">{{ selected.topic }}</small></div></div></header>
			<div ref="messagesEl" :class="$style.messages" @scroll="closeMenu">
				<div v-if="messages.length===0" :class="$style.welcome"><div :class="$style.welcomeIcon"><i :class="channelIcon(selected)"></i></div><h2>{{ selected.name }}</h2><p v-if="selected.topic&&selected.topic!==CATEGORY_TOPIC">{{ selected.topic }}</p></div>
				<article v-for="message in messages" :key="message.id" :class="$style.message" @contextmenu.prevent="openMessageMenu($event,message)" @pointerdown="startLongPress($event,message)" @pointerup="cancelLongPress" @pointercancel="cancelLongPress" @pointermove="cancelLongPress">
					<div :class="$style.avatar"><img v-if="authorAvatar(message)" :src="authorAvatar(message)!" alt=""><span v-else>{{ authorInitial(message) }}</span></div>
					<div :class="$style.messageContent"><div :class="$style.meta"><strong>{{ authorName(message) }}</strong><small v-if="authorHandle(message)">{{ authorHandle(message) }}</small><span v-if="message.botId" :class="$style.botBadge">BOT</span><i v-if="isPinned(message.id)" class="ti ti-pin" :class="$style.pinned"></i><time>{{ formatTime(message.createdAt) }}</time></div><div :class="$style.messageBody">{{ message.body }}</div><NookAutoTranslation kind="communityMessage" :objectId="message.id" :text="message.body"/></div>
				</article>
			</div>
			<form :class="$style.composer" @submit.prevent="send"><textarea v-model="draft" maxlength="8000" rows="1" :placeholder="`${l.send} #${selected.name}`" @keydown.enter.exact.prevent="send"></textarea><button class="_button" :class="$style.send" :disabled="!draft.trim()"><i class="ti ti-send"></i></button></form>
		</template>
		<div v-else :class="$style.empty">{{ l.noChannels }}</div>
	</main>

	<aside v-if="systemView===null" :class="$style.membersRail"><div :class="$style.railHeader"><strong>{{ l.members }}</strong><small>{{ activeMembers.length }}</small></div><div :class="$style.memberList"><div v-for="m in activeMembers" :key="m.userId" :class="$style.member"><div :class="$style.memberAvatar"><img v-if="m.avatarUrl" :src="m.avatarUrl" alt=""><span v-else>{{ memberInitial(m) }}</span></div><div :class="$style.memberText"><strong>{{ memberDisplayName(m) }}</strong><small>{{ memberHandle(m) }} · {{ roleLabel(m.baseRole) }}</small></div></div></div></aside>

	<div v-if="menu.open" :class="$style.contextMenu" :style="{left:`${menu.x}px`,top:`${menu.y}px`}" @click.stop><button v-if="canManagePins" class="_button" @click="togglePin"><i :class="isPinned(menu.message?.id||'')?'ti ti-pin-off':'ti ti-pin'"></i> {{ isPinned(menu.message?.id||'')?l.unpin:l.pin }}</button></div>
</section>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, nextTick, onBeforeUnmount, onMounted, reactive, ref, useCssModule, useTemplateRef } from 'vue';
import { nookApi } from './nook-api.js';
import { communityLabels as l } from './labels.js';
import NookAutoTranslation from './NookAutoTranslation.vue';
import NookCommunityAnnouncements from './NookCommunityAnnouncements.vue';
import NookCommunityMembers from './NookCommunityMembers.vue';
import NookCommunityRules from './NookCommunityRules.vue';
import NookCommunityVoice from './NookCommunityVoice.vue';
import type { CommunityChannel, CommunityMember, CommunityMessage, CommunityPin } from './types.js';

type SystemView='info'|'rules'|'announcements'|'members';
const CATEGORY_TOPIC='__nook_category__';
const props=defineProps<{communityId:string;pins:CommunityPin[];canManageChannels:boolean;canManageAnnouncements:boolean;canManageMembers:boolean;canManageRoles:boolean;canManageRules:boolean;canManagePins:boolean;canManageVoice:boolean;voiceEnabled:boolean}>();
const $style=useCssModule();
const XHeader=defineComponent({props:{icon:{type:String,required:true},title:{type:String,required:true}},setup(p){return()=>h('header',{class:$style.header},[h('div',{class:$style.heading},[h('i',{class:p.icon}),h('strong',p.title)])])}});
const channels=ref<CommunityChannel[]>([]),selected=ref<CommunityChannel|null>(null),systemView=ref<SystemView|null>(null),messages=ref<CommunityMessage[]>([]),members=ref<CommunityMember[]>([]),draft=ref(''),filter=ref(''),addOpen=ref(false),newCategoryName=ref(''),newChannelName=ref(''),newChannelKind=ref<CommunityChannel['kind']>('text'),newChannelParentId=ref(''),channelPins=ref<CommunityPin[]>([]); const messagesEl=useTemplateRef('messagesEl'); let timer:number|undefined,longPress:number|undefined;
const menu=reactive<{open:boolean;x:number;y:number;message:CommunityMessage|null}>({open:false,x:0,y:0,message:null});
const categoryIds=computed(()=>{const ids=new Set<string>();for(const c of channels.value){if(c.topic===CATEGORY_TOPIC)ids.add(c.id);if(c.parentId)ids.add(c.parentId)}return ids});
const categoryChannels=computed(()=>channels.value.filter(c=>categoryIds.value.has(c.id))),selectable=computed(()=>channels.value.filter(c=>!categoryIds.value.has(c.id))),visible=computed(()=>{const q=filter.value.trim().toLowerCase();return q?selectable.value.filter(c=>c.name.toLowerCase().includes(q)):selectable.value}),groups=computed(()=>categoryChannels.value.map(p=>({id:p.id,name:p.name,channels:visible.value.filter(c=>c.parentId===p.id)})).filter(g=>filter.value.trim()===''||g.channels.length>0)),ungrouped=computed(()=>visible.value.filter(c=>c.parentId==null)),textChannels=computed(()=>ungrouped.value.filter(c=>c.kind!=='voice')),voiceChannels=computed(()=>ungrouped.value.filter(c=>c.kind==='voice'));
const activeMembers=computed(()=>{const rank:Record<string,number>={owner:0,admin:1,moderator:2,member:3};return members.value.filter(m=>m.state==='active').slice().sort((a,b)=>(rank[a.baseRole]??9)-(rank[b.baseRole]??9))});
async function fetchChannels(){return await nookApi<CommunityChannel[]>('nook/community/channels/list',{communityId:props.communityId})}
function actualCount(items:CommunityChannel[]){const ids=new Set<string>();for(const c of items){if(c.topic===CATEGORY_TOPIC)ids.add(c.id);if(c.parentId)ids.add(c.parentId)}return items.filter(c=>!ids.has(c.id)).length}
async function loadChannels(){let loaded=await fetchChannels();if(actualCount(loaded)===0&&props.canManageChannels){try{await nookApi('nook/community/channels/create',{communityId:props.communityId,name:l.defaultChannelName,kind:'text'});loaded=await fetchChannels()}catch{}}channels.value=props.voiceEnabled?loaded:loaded.filter(c=>c.kind!=='voice');if(!selected.value||!selectable.value.some(c=>c.id===selected.value?.id))selected.value=selectable.value.find(c=>c.kind!=='voice')??selectable.value[0]??null;await Promise.all([loadMessages(),loadPins()])}
async function loadMembers(){members.value=await nookApi<CommunityMember[]>('nook/community/members/list',{communityId:props.communityId}).catch(()=>[])}
async function createCategory(){const name=newCategoryName.value.trim();if(!name)return;await nookApi('nook/community/channels/create',{communityId:props.communityId,name,kind:'text',topic:CATEGORY_TOPIC});newCategoryName.value='';await loadChannels()}
async function createChannel(){const name=newChannelName.value.trim();if(!name)return;if(newChannelKind.value==='voice'&&!props.voiceEnabled)return;await nookApi('nook/community/channels/create',{communityId:props.communityId,name,kind:newChannelKind.value,parentId:newChannelParentId.value||null});newChannelName.value='';newChannelKind.value='text';newChannelParentId.value='';await loadChannels()}
async function deleteChannel(channelId:string){const target=channels.value.find(c=>c.id===channelId);if(!target||!window.confirm(`${l.delete}: ${target.name}`))return;await nookApi('nook/community/channels/delete',{communityId:props.communityId,channelId});await loadChannels()}
async function loadMessages(){if(systemView.value||!selected.value||selected.value.kind==='voice'){messages.value=[];return}messages.value=await nookApi('nook/community/messages/list',{communityId:props.communityId,channelId:selected.value.id,limit:100})}
async function loadPins(){if(!selected.value||selected.value.kind==='voice'){channelPins.value=[];return}channelPins.value=await nookApi<CommunityPin[]>('nook/community/pins/list',{communityId:props.communityId,channelId:selected.value.id}).catch(()=>[])}
async function openSystem(view:SystemView){systemView.value=view;messages.value=[];channelPins.value=[];closeMenu();if(view==='members')await loadMembers()}
async function selectChannel(c:CommunityChannel){systemView.value=null;selected.value=c;closeMenu();await Promise.all([loadMessages(),loadPins()]);await scrollBottom()}
async function send(){if(systemView.value||!selected.value||selected.value.kind==='voice'||!draft.value.trim())return;await nookApi('nook/community/messages/create',{communityId:props.communityId,channelId:selected.value.id,body:draft.value.trim()});draft.value='';await loadMessages();await scrollBottom()}
function pinFor(id:string){return channelPins.value.find(p=>p.kind==='message'&&p.targetId===id)} function isPinned(id:string){return !!pinFor(id)}
function openMessageMenu(e:MouseEvent|PointerEvent,message:CommunityMessage){if(!props.canManagePins)return;const x=Math.min(e.clientX,window.innerWidth-180),y=Math.min(e.clientY,window.innerHeight-70);menu.open=true;menu.x=x;menu.y=y;menu.message=message}
function startLongPress(e:PointerEvent,message:CommunityMessage){if(e.pointerType==='mouse'||!props.canManagePins)return;cancelLongPress();const x=e.clientX,y=e.clientY;longPress=window.setTimeout(()=>openMessageMenu({clientX:x,clientY:y} as PointerEvent,message),550)} function cancelLongPress(){if(longPress){window.clearTimeout(longPress);longPress=undefined}} function closeMenu(){menu.open=false;menu.message=null;cancelLongPress()}
async function togglePin(){const message=menu.message;if(!message||!selected.value)return;const existing=pinFor(message.id);if(existing)await nookApi('nook/community/pins/delete',{communityId:props.communityId,pinId:existing.id});else await nookApi('nook/community/pins/create',{communityId:props.communityId,channelId:selected.value.id,kind:'message',targetId:message.id,label:message.body.slice(0,80)});closeMenu();await loadPins()}
function channelIcon(c:CommunityChannel){if(c.kind==='announcement')return'ti ti-speakerphone';if(c.kind==='media')return'ti ti-photo';if(c.kind==='forum')return'ti ti-messages';if(c.kind==='voice')return'ti ti-volume';return'ti ti-hash'}
function memberForMessage(m:CommunityMessage){return m.userId?members.value.find(x=>x.userId===m.userId)??null:null} function memberDisplayName(m:CommunityMember){return m.nickname||m.name||m.username} function memberHandle(m:CommunityMember){return`@${m.username}${m.host?`@${m.host}`:''}`} function memberInitial(m:CommunityMember){return memberDisplayName(m).slice(0,1).toUpperCase()} function authorName(m:CommunityMessage){if(m.botId)return m.botId;const u=memberForMessage(m);return u?memberDisplayName(u):'Unknown'} function authorHandle(m:CommunityMessage){if(m.botId)return'';const u=memberForMessage(m);return u?memberHandle(u):''} function authorAvatar(m:CommunityMessage){return memberForMessage(m)?.avatarUrl??null} function authorInitial(m:CommunityMessage){return authorName(m).slice(0,1).toUpperCase()} function roleLabel(r:string){if(r==='owner')return l.owner;if(r==='admin')return l.administrator;if(r==='moderator')return l.moderator;return l.member} function formatTime(v:string){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))} async function scrollBottom(){await nextTick();if(messagesEl.value)messagesEl.value.scrollTop=messagesEl.value.scrollHeight}
function outsideClick(){closeMenu()}
onMounted(async()=>{window.addEventListener('click',outsideClick);await Promise.all([loadChannels(),loadMembers()]);await scrollBottom();timer=window.setInterval(()=>{if(!systemView.value)void loadMessages()},3000)});onBeforeUnmount(()=>{window.removeEventListener('click',outsideClick);if(timer)window.clearInterval(timer);cancelLongPress()});
</script>

<style lang="scss" module>
